@push('scripts')<script>document.addEventListener('click',e=>{const open=e.target.closest('[data-return-reject-toggle]'),close=e.target.closest('[data-return-reject-cancel]');if(open){const panel=document.getElementById('returnReject'+open.dataset.returnRejectToggle);panel?.classList.add('is-open');panel?.querySelector('textarea')?.focus()}if(close){document.getElementById('returnReject'+close.dataset.returnRejectCancel)?.classList.remove('is-open')}});document.addEventListener('input',e=>{const field=e.target.closest('.return-reject-panel textarea');if(!field)return;const panel=field.closest('.return-reject-panel'),valid=field.value.trim().length>=10;panel.querySelector('button[type="submit"]').disabled=!valid;panel.querySelector('.return-reject-error').textContent=valid?'':'Enter at least 10 characters to reject.';document.querySelector('[data-reject-count="'+field.id.replace('rejectReason','')+'"]').textContent=field.value.length+'/1500';field.classList.toggle('is-invalid',field.value.length>0&&!valid)});</script>@endpush
